ser_script and order == "plugin-first": subprocess.run(["node", browser_script, runtime.base_url, sid, "plugin-pending"], check=True, timeout=60, stdout=sys.stdout, stderr=sys.stderr, **command_window_options()) if prior: assert accepted == prior assert runtime.request("POST", endpoint)["delayedRestart"] == accepted # A second physical tool-list update joins the same runtime intent. bindings[0]["mode"] = "standalone" updated = runtime.request("PATCH", f"/api/sessions/{sid}", json={"pluginBindings": bindings}) assert updated["delayedRestart"] == accepted assert process.is_running() and process.create_time() == created assert len(_received(runtime, cwd=s["workdir"])) == 1 disk = _read_session_metadata(runtime.data_root / "sessions" / f"{sid}.json") assert disk["adapter_config"]["plugin_bindings"] == bindings runtime.gates["hold-A"].touch() completed = _wait_for(lambda: ( state if (state := runtime.request("GET", endpoint)["delayedRestart"])["status"] == "completed" else None), label="plugin/delayed restart completion") queue = runtime.request("GET", f"/api/sessions/{sid}/queue") row = next(item for item in queue["items"] if item["id"] == locked) assert row["meta"]["locked"] same = runtime.request("PATCH", f"/api/sessions/{sid}", json={"pluginBindings": bindings}) assert same["pluginApplyStatus"] == "applied" and not same.get("requireRestart") assert runtime.request("GET", endpoint)["delayedRestart"] == completed assert not _received(runtime, cwd=s["workdir"], text="plugin-next") if active: manager_disk = _read_session_metadata(runtime.data_root / "sessions" / f"{manager['id']}.json") > assert len(manager_disk["queue_pending"]) == 1 E assert 0 == 1 E + where 0 = len([])
